from vlb_traj import Session
from scipy.spatial.transform import Rotation
import numpy as np, math, json
s=Session(); s.record_start(); b=np.array(s.state()['entities']['buzz_lightyear']['position'])
q0=Rotation.from_euler('xyz',[0,-math.pi/2,-math.pi/2]).as_quat(); quat=[q0[3],*q0[:3]]

def goto(p,grip,spacing=.04):
 st=s.state(); cur=np.array(st['robot']['joint_positions']); ik=s.ik(np.array(p).tolist(),quat)
 if not ik['success']: print('IKFAIL',np.round(p,3),flush=True); return False
 goal=np.asarray(ik['joint_positions']); n=max(3,int(np.max(abs(goal-cur))/spacing))
 for t in np.linspace(0,1,n+1)[1:]: s.step(np.r_[cur*(1-t)+goal*t,grip])
 return True
# approach along positive Y, reaching near center
hover=b+np.array([0,-.10,0]); grasp=b+np.array([0,0,0])
print('ik',s.ik(grasp.tolist(),quat)['success'],flush=True)
if goto(hover,[.04,.04]):
 for y in np.linspace(hover[1],grasp[1],8)[1:]:
  if not goto([b[0],y,b[2]],[.04,.04],.025): break
st=s.state(); print('AT GRASP','tcp',np.round(st['robot']['tcp_position'],3),'toy',np.round(st['entities']['buzz_lightyear']['position'],3),'f',np.round(st['robot']['gripper_positions'],3),flush=True)
for w in np.linspace(.04,.002,12): s.step(np.r_[s.state()['robot']['joint_positions'],[w,w]])
st=s.state(); print('CLOSED','f',np.round(st['robot']['gripper_positions'],3),'toy',np.round(st['entities']['buzz_lightyear']['position'],3),flush=True)
for z in np.arange(b[2]+.01,b[2]+.061,.01): goto([b[0],b[1],z],[.012,.012],.025)
st=s.state(); toy=np.array(st['entities']['buzz_lightyear']['position']); print('LIFT','toy',np.round(toy,3),'delta',np.round(toy-b,3),'tcp',np.round(st['robot']['tcp_position'],3),'f',np.round(st['robot']['gripper_positions'],3),flush=True)
if toy[2]>b[2]+.035:
 for y in np.arange(b[1],.05,-.01):
  goto([b[0],y,.96],[.012,.012],.025)
  if int(round(y*100))%5==0:
   st=s.state(); toy=np.array(st['entities']['buzz_lightyear']['position']); print('CARRY y',round(y,2),'toy',np.round(toy,3),flush=True)
   if toy[2]<.9: break
print('STATUS',json.dumps(s.status(),indent=2),flush=True)
a=s.record_stop()
if s.status()['success']: s.save_trajectory(a,'/app/output/trajectory.npz'); print('SAVED',a.shape,flush=True)
else: s.save_trajectory(a,'/app/output/side_grasp.npz'); print('FAILED',a.shape,flush=True)
s.close()
